<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>2048</title>
<style>
  :root{
    --bg:#12141a;
    --panel:#1c1f27;
    --grid:#2a2e39;
    --cell:#333846;
    --text:#f5f5f7;
    --accent:#f0a33c;
  }
  *{box-sizing:border-box;}
  html,body{margin:0;padding:0;}
  body{
    min-height:100vh;
    background:var(--bg);
    color:var(--text);
    font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:center;
    padding:24px;
    gap:16px;
  }
  h1{
    margin:0;
    font-size:38px;
    letter-spacing:2px;
    color:var(--accent);
  }
  .hud{
    display:flex;
    align-items:center;
    gap:12px;
    width:min(92vw,440px);
    justify-content:space-between;
  }
  .scorebox{
    background:var(--panel);
    border-radius:10px;
    padding:8px 18px;
    text-align:center;
    min-width:120px;
  }
  .scorebox .label{
    font-size:11px;
    text-transform:uppercase;
    letter-spacing:1.5px;
    color:#8b90a0;
  }
  #score{
    font-size:26px;
    font-weight:700;
    line-height:1.2;
  }
  #reset{
    background:var(--accent);
    color:#1b1b1b;
    border:none;
    border-radius:10px;
    padding:12px 20px;
    font-size:15px;
    font-weight:700;
    cursor:pointer;
    letter-spacing:.5px;
  }
  #reset:hover{filter:brightness(1.1);}
  #reset:active{transform:translateY(1px);}
  #board{
    width:min(92vw,440px);
    aspect-ratio:1/1;
    background:var(--grid);
    border-radius:12px;
    padding:10px;
    display:grid;
    grid-template-columns:repeat(4,1fr);
    grid-template-rows:repeat(4,1fr);
    gap:10px;
  }
  .tile{
    background:var(--cell);
    border-radius:8px;
    display:flex;
    align-items:center;
    justify-content:center;
    font-weight:800;
    font-size:clamp(18px,6vw,34px);
    color:#f7f7f7;
    user-select:none;
  }
  .tile.empty{color:transparent;background:#272b35;}
  .v2{background:#3f4657;}
  .v4{background:#4b5468;}
  .v8{background:#c98443;}
  .v16{background:#d97b3c;}
  .v32{background:#e0653c;}
  .v64{background:#e84b34;}
  .v128{background:#e6c04a;color:#211f10;}
  .v256{background:#e8c53c;color:#211f10;}
  .v512{background:#eccb2f;color:#211f10;}
  .v1024{background:#f0d223;color:#211f10;font-size:clamp(14px,4.6vw,27px);}
  .v2048{background:#f5da12;color:#211f10;font-size:clamp(14px,4.6vw,27px);}
  .vbig{background:#2ecfa1;color:#0d2a22;font-size:clamp(12px,4vw,23px);}
  .msg{
    min-height:22px;
    font-size:14px;
    color:#9aa0b2;
    letter-spacing:.5px;
  }
</style>
</head>
<body>
  <h1>2048</h1>
  <div class="hud">
    <div class="scorebox">
      <div class="label">Score</div>
      <div id="score">0</div>
    </div>
    <button id="reset">New Game</button>
  </div>
  <div id="board"></div>
  <div class="msg" id="msg">Use the arrow keys to move.</div>

<script>
(function(){
  var SIZE = 4;
  var grid = [];
  var scoreVal = 0;

  var boardEl = document.getElementById('board');
  var scoreEl = document.getElementById('score');
  var resetEl = document.getElementById('reset');
  var msgEl = document.getElementById('msg');

  function makeEmpty(){
    var g = [];
    for(var r=0;r<SIZE;r++){
      var row=[];
      for(var c=0;c<SIZE;c++) row.push(0);
      g.push(row);
    }
    return g;
  }

  function cloneGrid(g){
    return g.map(function(row){ return row.slice(); });
  }

  // ---- rendering ----
  var cells = [];
  function buildCells(){
    boardEl.innerHTML = '';
    cells = [];
    for(var i=0;i<SIZE*SIZE;i++){
      var d = document.createElement('div');
      d.className = 'tile empty';
      d.textContent = '0';
      boardEl.appendChild(d);
      cells.push(d);
    }
  }

  function classFor(v){
    if(v === 0) return 'tile empty';
    if(v > 2048) return 'tile vbig';
    return 'tile v'+v;
  }

  function render(){
    for(var r=0;r<SIZE;r++){
      for(var c=0;c<SIZE;c++){
        var v = grid[r][c];
        var el = cells[r*SIZE+c];
        el.className = classFor(v);
        el.textContent = v === 0 ? '' : String(v);
        el.setAttribute('data-value', String(v));
        el.setAttribute('data-row', String(r));
        el.setAttribute('data-col', String(c));
      }
    }
    scoreEl.textContent = String(scoreVal);
  }

  // ---- core mechanics ----
  // Slide+merge a single line toward index 0. Returns {line, gained, changed}
  function collapseLine(line){
    var vals = line.filter(function(v){ return v !== 0; });
    var out = [];
    var gained = 0;
    var i = 0;
    while(i < vals.length){
      if(i+1 < vals.length && vals[i] === vals[i+1]){
        var merged = vals[i]*2;
        out.push(merged);
        gained += merged;
        i += 2;
      } else {
        out.push(vals[i]);
        i += 1;
      }
    }
    while(out.length < line.length) out.push(0);
    var changed = false;
    for(var k=0;k<line.length;k++){
      if(out[k] !== line[k]){ changed = true; break; }
    }
    return {line: out, gained: gained, changed: changed};
  }

  function getLine(g, dir, idx){
    // returns array ordered so that index 0 is the direction the tiles move toward
    var line = [];
    var i;
    if(dir === 'left'){
      for(i=0;i<SIZE;i++) line.push(g[idx][i]);
    } else if(dir === 'right'){
      for(i=SIZE-1;i>=0;i--) line.push(g[idx][i]);
    } else if(dir === 'up'){
      for(i=0;i<SIZE;i++) line.push(g[i][idx]);
    } else { // down
      for(i=SIZE-1;i>=0;i--) line.push(g[i][idx]);
    }
    return line;
  }

  function setLine(g, dir, idx, line){
    var i;
    if(dir === 'left'){
      for(i=0;i<SIZE;i++) g[idx][i] = line[i];
    } else if(dir === 'right'){
      for(i=0;i<SIZE;i++) g[idx][SIZE-1-i] = line[i];
    } else if(dir === 'up'){
      for(i=0;i<SIZE;i++) g[i][idx] = line[i];
    } else {
      for(i=0;i<SIZE;i++) g[SIZE-1-i][idx] = line[i];
    }
  }

  function applyMove(g, dir){
    var gained = 0, changed = false;
    for(var idx=0; idx<SIZE; idx++){
      var line = getLine(g, dir, idx);
      var res = collapseLine(line);
      if(res.changed) changed = true;
      gained += res.gained;
      setLine(g, dir, idx, res.line);
    }
    return {changed: changed, gained: gained};
  }

  function emptyCells(g){
    var list = [];
    for(var r=0;r<SIZE;r++)
      for(var c=0;c<SIZE;c++)
        if(g[r][c] === 0) list.push([r,c]);
    return list;
  }

  function spawn(){
    var list = emptyCells(grid);
    if(!list.length) return false;
    var pick = list[Math.floor(Math.random()*list.length)];
    grid[pick[0]][pick[1]] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  function canMove(){
    for(var r=0;r<SIZE;r++){
      for(var c=0;c<SIZE;c++){
        if(grid[r][c] === 0) return true;
        if(c+1<SIZE && grid[r][c] === grid[r][c+1]) return true;
        if(r+1<SIZE && grid[r][c] === grid[r+1][c]) return true;
      }
    }
    return false;
  }

  function reset(){
    grid = makeEmpty();
    scoreVal = 0;
    spawn();
    spawn();
    msgEl.textContent = 'Use the arrow keys to move.';
    render();
  }

  function move(dir){
    if(['left','right','up','down'].indexOf(dir) === -1) return false;
    var res = applyMove(grid, dir);
    if(!res.changed) return false;
    scoreVal += res.gained;
    spawn();
    render();
    if(!canMove()) msgEl.textContent = 'Game over — no moves left.';
    return true;
  }

  function setBoard(arr){
    var g = makeEmpty();
    for(var r=0;r<SIZE;r++){
      for(var c=0;c<SIZE;c++){
        var v = 0;
        if(arr && arr[r] && typeof arr[r][c] !== 'undefined' && arr[r][c] !== null){
          v = Number(arr[r][c]) || 0;
        }
        g[r][c] = v;
      }
    }
    grid = g;
    render();
  }

  // ---- input ----
  var keyMap = {
    ArrowLeft:'left', ArrowRight:'right', ArrowUp:'up', ArrowDown:'down',
    Left:'left', Right:'right', Up:'up', Down:'down'
  };
  document.addEventListener('keydown', function(e){
    var dir = keyMap[e.key];
    if(!dir) return;
    e.preventDefault();
    move(dir);
  });

  resetEl.addEventListener('click', function(){ reset(); });

  // touch support (optional convenience)
  var tsx=null, tsy=null;
  boardEl.addEventListener('touchstart', function(e){
    if(e.touches.length!==1) return;
    tsx = e.touches[0].clientX; tsy = e.touches[0].clientY;
  }, {passive:true});
  boardEl.addEventListener('touchend', function(e){
    if(tsx===null) return;
    var t = e.changedTouches[0];
    var dx = t.clientX - tsx, dy = t.clientY - tsy;
    tsx = tsy = null;
    if(Math.max(Math.abs(dx),Math.abs(dy)) < 24) return;
    if(Math.abs(dx) > Math.abs(dy)) move(dx>0?'right':'left');
    else move(dy>0?'down':'up');
  });

  window.game = {
    size: SIZE,
    reset: reset,
    move: move,
    board: function(){ return cloneGrid(grid); },
    setBoard: setBoard,
    score: function(){ return scoreVal; }
  };

  buildCells();
  reset();
})();
</script>
</body>
</html>
